#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;
class Room{protected:int id;double price;bool available=true;public:Room(int i,double p):id(i),price(p){}virtual~Room()=default;int getId()const{return id;}bool isAvailable()const{return available;}virtual string type()const=0;double nightly()const{return price;}void book(){if(!available)throw runtime_error("unavailable");available=false;}void release(){available=true;}void show()const{cout<<id<<" | "<<type()<<" | "<<price<<"/night | "<<(available?"Available":"Booked")<<'\n';}};class SingleRoom:public Room{public:SingleRoom(int i):Room(i,750){}string type()const override{return"Single";}};class DoubleRoom:public Room{public:DoubleRoom(int i):Room(i,1200){}string type()const override{return"Double";}};class Suite:public Room{public:Suite(int i):Room(i,2500){}string type()const override{return"Suite";}};
struct Reservation{int id,roomId,nights;string customer,checkIn,checkOut;double total;bool active=true;};class Hotel{vector<shared_ptr<Room>>rooms;vector<Reservation>res;int next=1;shared_ptr<Room>find(int id){for(auto&r:rooms)if(r->getId()==id)return r;return{};}public:Hotel(){for(int i=1;i<=4;++i)rooms.push_back(make_shared<SingleRoom>(i));for(int i=5;i<=8;++i)rooms.push_back(make_shared<DoubleRoom>(i));for(int i=9;i<=10;++i)rooms.push_back(make_shared<Suite>(i));}void available()const{for(auto&r:rooms)if(r->isAvailable())r->show();}void reserve(){available();int id,n;string name,in,out;cout<<"Room ID: ";cin>>id;auto r=find(id);if(!r||!r->isAvailable())return;cout<<"Customer: ";cin>>ws;getline(cin,name);cout<<"Check-in: ";getline(cin,in);cout<<"Check-out: ";getline(cin,out);cout<<"Nights: ";cin>>n;if(n<=0)return;r->book();double t=n*r->nightly();res.push_back({next++,id,n,name,in,out,t,true});ofstream("reservations.txt",ios::app)<<res.back().id<<'|'<<id<<'|'<<name<<'|'<<in<<'|'<<out<<'|'<<n<<'|'<<t<<'\n';cout<<"Total "<<t<<'\n';}void cancel(){int id;cin>>id;for(auto&x:res)if(x.id==id&&x.active){x.active=false;if(auto r=find(x.roomId))r->release();cout<<"Cancelled\n";return;}}void list()const{for(auto&x:res)cout<<x.id<<" | room "<<x.roomId<<" | "<<x.customer<<" | "<<x.nights<<" nights | "<<x.total<<" | "<<(x.active?"Active":"Cancelled")<<'\n';}void run(){for(;;){cout<<"\nHotel\n1 Available 2 Reserve 3 Cancel 4 Reservations 0 Exit\n";int c;if(!(cin>>c)||c==0)break;if(c==1)available();else if(c==2)reserve();else if(c==3)cancel();else if(c==4)list();}}};int main(){Hotel{}.run();}
